head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.gBondYn = js_bond_yn;
scwin.vScrenID = 'ULDSTF26604.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_read_schdl = function() {
    var parentWin = $c.frame.path("../");
    var paramObj = parentWin.gParamObj;
    if (paramObj == undefined) return;
    var vIBAS_YY = paramObj.param1;
    var vIBAS_ACNTCLS_MM = paramObj.param2;
    var vIGUBUN = paramObj.param3;
    var url = "/SubmitStatus.do?method=readSubmitDeadline";
    url += "&BAS_YY=" + vIBAS_YY;
    url += "&BAS_ACNTCLS_MM=" + vIBAS_ACNTCLS_MM;
    url += "&GUBUN=" + vIGUBUN;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    //alert('[url]'+url);
    dts_Comcompany.DataID = encodeURI(url);
    dts_Comcompany.Reset();
};
scwin.fn_Save = function() {
    if (confirm("수정하시겠습니까?")) {
        trs_Save.Action = "/SubmitStatus.do?method=modifySubmitDeadline&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Comcompany)";
        trs_Save.Post();
    } else {
        return false;
    }
};
scwin.fn_HideDebugCtrls = function() {
    $c.stf.showObj(txb_WRTRPT_KIND_CD, false);
};
scwin.img_SDATE_onclick = function() {
    popUpCalendar2(edt_WRTRPT_SUBMIT_SCHDL_DD);
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_Comcompany_OnLoadCompleted = function(rowcount) {
    dts_Comcompany.setCellData(1, "FLAG", "Y");

    //제출마감일이 과거일자면 저장 버튼이 보이지않게 한다.
    var gSUBMIT_SCHDL_DD = dts_Comcompany.getCellData(1, "WRTRPT_SUBMIT_SCHDL_DD");
    if (gSUBMIT_SCHDL_DD < $c.ut.cGetToday("yyyymmdd")) {
        $c.stf.showObj(btn_Save, false);
    }
};
scwin.trs_Save_OnFail = function() {
    $c.stf.alert_error(trs_Save); ///('trs_Save.OnFail()');

};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
    var fr_fn_Search = $c.frame.path("../").fn_Search;
    fr_fn_Search();
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_HideDebugCtrls();
    scwin.fn_read_schdl();

    //채권팀일시 저장버튼 보이지않게 한다.
    if (scwin.gBondYn == 'Y') {
        $c.stf.showObj(btn_Save, false);
    }
};
